#define R iResolution.xy
#define M iMouse
#define Main void mainImage(out vec4 Q, in vec2 U)
#define A(U) texture(iChannel0, (U)/R)
#define B(U) texture(iChannel1, (U)/R)
#define C(U) texture(iChannel2, (U)/R)
#define D(U) texture(iChannel3, (U)/R)

// Distance from point p to line segment (a,b)
float line(vec2 p, vec2 a, vec2 b) {
    float t = clamp(dot(p - a, b - a) / dot(b - a, b - a), 0.0, 1.0);
    return length((a + t * (b - a)) - p);
}

// A simple perpendicular helper
vec2 perp(vec2 u) {
    return vec2(-u.y, u.x);
}

// -------------------- Hilbert Curve Helpers --------------------

// Rotate/flip a quadrant in Hilbert indexing
ivec2 hilbertRot(int n, ivec2 xy, int rx, int ry)
{
    if (ry == 0) {
        if (rx == 1) {
            xy.x = n - 1 - xy.x;
            xy.y = n - 1 - xy.y;
        }
        // swap x,y
        int t = xy.x;
        xy.x = xy.y;
        xy.y = t;
    }
    return xy;
}

// Convert 1D Hilbert index -> 2D in [0,1]
vec2 hilbert2D(int index, int order)
{
    // side length = 2^order
    int n = 1 << order;
    int x = 0;
    int y = 0;
    int t = index;
    for (int s = 0; s < 16; s++) {
        if (s >= order) break;
        int rx = (t / 2) & 1;
        int ry = (t ^ rx) & 1;
        ivec2 xy = hilbertRot(1 << s, ivec2(x, y), rx, ry);
        x = xy.x + (rx << s);
        y = xy.y + (ry << s);
        t /= 4;
    }
    return vec2(x, y) / float(n);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Current pixel position
    vec2 U = fragCoord;

    // Start with a blank (black) background each frame
    vec4 Q = vec4(0.0);

    // Increase Hilbert order every 3 seconds: order in [1..5]
    int order = int(floor(iTime / 3.0)) + 1;
    order = min(order, 3);  // Stop multiplying after 3 steps

    // Number of Hilbert points: 2^(2*order)
    int totalPoints = 1 << (2 * order);

    // Fit the curve nicely in the center of the screen.
    // We'll use 80% of the smaller dimension as the “square” side
    float side = min(iResolution.x, iResolution.y) * 0.8;
    // Offset = half of leftover space, so we center on screen
    vec2 offset = (iResolution.xy - side) * 0.5;

    // Draw each segment
    for(int i = 0; i < 65536; i++)
    {
        if (i >= totalPoints - 1) break;

        // endpoints in pixel space
        vec2 p0 = hilbert2D(i,   order) * side + offset;
        vec2 p1 = hilbert2D(i+1, order) * side + offset;

        // distance to the fragment
        float dist = line(U, p0, p1);

        // color variation (you can change this to taste)
        vec3 col = sin(vec3(1.0, 2.0, 3.0) + iTime + float(i));

        // exponential stroke falloff
        float stroke = exp(-0.5 * dist);

        // accumulate via max
        Q = max(Q, vec4(col, 1.0) * stroke);
    }

    // Output final color
    fragColor = Q;
}

Main {

    Q = .99*C(U);

    vec2 d = vec2(cos(float(iFrame)),sin(float(iFrame)));

    for (float i = 0.; i < 300.; i++) {
        U += d;
        vec4 q = A(U);
        if (length(q.w)>.5) {
            Q += .01*max(q,0.);
            break;
        }
    }
}
